#include <cuda_runtime.h>
#include <vector>
#include <fstream>
#include <chrono>
#include <cmath>
#include "../phmm-cuda/constants_types.h"
#include "../phmm-cuda/kernel.h"
void ck(cudaError_t e){if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(2);}}
std::vector<double>load(const char*f){std::ifstream io(f,std::ios::binary|std::ios::ate);size_t z=io.tellg();std::vector<double>v(z/8);io.seekg(0);io.read((char*)v.data(),z);return v;}
const int sizes[6]={3936,3936,3936,288,32,8};
struct Case{int repeat,zero;std::vector<double>input[6];double*p[6];};
void reset(Case&c){for(int k=0;k<2;k++){std::vector<double>v=c.input[k];v.insert(v.begin(),-12345.);v.push_back(-12345.);ck(cudaMemcpy(c.p[k],v.data(),v.size()*8,cudaMemcpyDefault));}ck(cudaDeviceSynchronize());}
void pipeline(Case&c){double*s=c.p[0]+1,*d=c.p[1]+1;for(int r=0;r<c.repeat;r++)for(int i=1;i<=11;i++)for(int j=1;j<=40;j++){pair_HMM_forward<<<4,2>>>(i,j,(fArray*)s,(tArray*)(c.p[3]+1),(fArray*)(c.p[2]+1),(lArray*)(c.p[4]+1),(sArray*)(c.p[5]+1),(fArray*)d);std::swap(s,d);}ck(cudaDeviceSynchronize());}
int main(){auto f=load(PH_FIXTURE),o=load(PH_ORACLE),budget=load(PH_BUDGET);std::vector<Case>cases;size_t pos=1;for(int ci=0;ci<int(f[0]);ci++){Case c;c.repeat=f[pos++];c.zero=f[pos++];for(int k:{0,2,3,4,5}){c.input[k].assign(f.begin()+pos,f.begin()+pos+sizes[k]);pos+=sizes[k];}c.input[1]=c.input[0];for(int k=0;k<6;k++){auto v=c.input[k];v.insert(v.begin(),-12345.);v.push_back(-12345.);ck(cudaMalloc(&c.p[k],v.size()*8));ck(cudaMemcpy(c.p[k],v.data(),v.size()*8,cudaMemcpyDefault));}cases.push_back(c);}cudaFuncAttributes at;ck(cudaFuncGetAttributes(&at,pair_HMM_forward));printf("STUDY_NATIVE_RESOURCE static_shared_bytes=%zu registers=%d\n",at.sharedSizeBytes,at.numRegs);for(auto&c:cases){reset(c);pipeline(c);}for(int trial=1;trial<=5;trial++){auto payload=f;double total=0,maxerr=0,maxratio=0;std::vector<double>times;bool ok=true;for(auto&c:cases){reset(c);auto start=std::chrono::steady_clock::now();pipeline(c);double t=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();times.push_back(t);total+=t;for(int k=0;k<6;k++){size_t off=payload.size();payload.resize(off+sizes[k]+2);ck(cudaMemcpy(payload.data()+off,c.p[k],(sizes[k]+2)*8,cudaMemcpyDefault));}}for(size_t i=0;i<o.size();i++){double x=payload[f.size()+i],e=fabs(x-o[i]),b=budget[i];maxerr=std::max(maxerr,e);maxratio=std::max(maxratio,b>0?e/b:e==0?0:1e300);ok&=std::isfinite(x)&&e<=b;}std::string path="trial_"+std::to_string(trial)+".bin";std::ofstream out(path,std::ios::binary);out.write((char*)payload.data(),payload.size()*8);out.close();printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.17g,\"max_rel_error\":null,\"max_error_budget_ratio\":%.17g,\"timing_region\":\"sum3_defined_storage_source_440cell_swap_pipelines_context_complete\",\"jit_excluded\":true,\"internal_repeats\":1,\"timed_kernel_calls\":1760,\"case_times_seconds\":[%.17g,%.17g,%.17g],\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,total,ok?"true":"false",payload.size(),maxerr,maxratio,times[0],times[1],times[2],path.c_str(),payload.size());if(!ok)return 3;}return 0;}
